const modelContent={reason:{name:'Qwen3.5',title:'现场智能问答',desc:'工程资料 · 测量读数 · 现场问题',inputs:['工程资料','测量读数','现场问题'],image:'model-qa.png',alt:'板端现场问答界面'},vision:{name:'Qwen2.5-VL',title:'图像智能问答',desc:'现场画面 · 温度读数',inputs:['现场画面','温度读数','采样时刻'],image:'overview.png',alt:'画面、热像与板端问答界面'},speech:{name:'Qwen3-ASR',title:'语音识别与转写',desc:'语音片段 · 转写文字',inputs:['语音片段','时间范围','转写文字'],image:'voice.png',alt:'语音轨道与转写界面'},video:{name:'Qwen3-VL',title:'视频多帧理解',desc:'视频片段 · 多帧理解',inputs:['视频片段','多帧图像','时间戳'],image:'vision.png',alt:'视觉分析界面'}};
document.querySelectorAll('[data-model]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-model]').forEach(b=>{b.setAttribute('aria-selected',b===button);b.tabIndex=b===button?0:-1});const data=modelContent[button.dataset.model];document.querySelector('#model-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#model-name').textContent=data.name;document.querySelector('#model-title').innerHTML=data.title.split('<br>').map(s=>`<span class="title-line">${s}</span>`).join('');document.querySelector('#model-desc').textContent=data.desc;document.querySelector('#model-inputs').innerHTML=data.inputs.map(s=>`<span>${s}</span>`).join('');document.querySelector('#model-image').src='assets/'+data.image;document.querySelector('#model-image').alt=data.alt;animateContent(document.querySelector('#model-panel'))}));
document.querySelectorAll('.thermal-screen img,.visual-screen img,.model-media img,.voice-screen img').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');function open(){imageTrigger=img;document.querySelector('#full-image').src=img.src;document.querySelector('#full-image').alt=img.alt;viewer.showModal();document.body.style.overflow='hidden'}img.addEventListener('click',open);img.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}})});
